function translateUiText(value:string,dictionary:Record<string,string>){
  const exact=dictionary[value];
  if(exact)return exact;
  const tableRange=value.match(/^Showing (.+) of (.+) rows$/);
  if(tableRange)return `एकूण ${tableRange[2]} पैकी ${tableRange[1]} नोंदी`;
  const pageRange=value.match(/^Page (\d+) of (\d+)$/);
  if(pageRange)return `${pageRange[2]} पैकी ${pageRange[1]} पान`;
  const itemCount=value.match(/^(\d+) items?$/);
  if(itemCount)return `${itemCount[1]} वस्तू`;
  const minutes=value.match(/^(\d+) min(?:utes?)? ago$/);
  if(minutes)return `${minutes[1]} मिनिटांपूर्वी`;
  const minuteCount=value.match(/^(\d+) min$/);
  if(minuteCount)return `${minuteCount[1]} मिनिटे`;
  const count=value.match(/^(\d+) (warehouses|franchises|stops|visible)$/);
  if(count){const units:Record<string,string>={warehouses:'वेअरहाऊसेस',franchises:'फ्रँचायझी',stops:'थांबे',visible:'दिसत आहेत'};return `${count[1]} ${units[count[2]]}`;}
  const allocation=value.match(/^(\d+) orders? need allocation decision$/);
  if(allocation)return `${allocation[1]} ऑर्डरसाठी मालवाटपाचा निर्णय आवश्यक`;
  const blocked=value.match(/^(\d+) orders? · (₹[\d,.]+) blocked$/);
  if(blocked)return `${blocked[1]} ऑर्डर्स · ${blocked[2]} रक्कम रोखली`;
  const prefix=Object.keys(dictionary).find(key=>key.endsWith(' ')&&value.startsWith(key));
  const suffix=Object.keys(dictionary).find(key=>key.startsWith(' ')&&value.endsWith(key));
  let translated=value;
  if(prefix)translated=dictionary[prefix]+translated.slice(prefix.length);
  if(suffix)translated=translated.slice(0,-suffix.length)+dictionary[suffix];
  return translated===value?undefined:translated;
}
const textSnapshots=new WeakMap<Node,{source:string;translated:string}>();
const attributeSnapshots=new WeakMap<Element,Map<string,{source:string;translated:string}>>();

export function LanguageProvider({children}:{children:React.ReactNode}){
  const [language,setLanguageState]=useState<Language>('en');
  useEffect(()=>{const saved=window.localStorage.getItem(STORAGE_KEY);if(saved==='mr'||saved==='en')setLanguageState(saved)},[]);
  useEffect(()=>{window.localStorage.setItem(STORAGE_KEY,language);document.documentElement.lang=language==='mr'?'mr':'en'},[language]);
  useEffect(()=>{
    let frame=0;
    const pending=new Set<Node>();
    const ignored=(node:Node)=>node.parentElement?.closest('[data-no-translate],.invoice-paper');
    const translateNode=(root:Node)=>{
      if(root instanceof Element&&root.closest('[data-no-translate],.invoice-paper'))return;
      const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
      const textNodes:Node[]=[];
      if(root.nodeType===Node.TEXT_NODE)textNodes.push(root);
      let node:Node|null;
      while((node=walker.nextNode()))textNodes.push(node);
      for(const textNode of textNodes){
        if(ignored(textNode))continue;
        const source=textNode.nodeValue||'';
        const snapshot=textSnapshots.get(textNode);
        if(language==='en'&&snapshot&&source===snapshot.translated){textNode.nodeValue=snapshot.source;continue;}
        const value=source.trim();
        const replacement=language==='mr'?translateUiText(value,domMr):undefined;
        if(replacement&&replacement!==value&&textNode.nodeValue){
          const option=textNode.parentElement?.closest('option');
          if(option){
            if(language==='mr')option.dataset.originalLanguageValue=value;
            const originalValue=option.dataset.originalLanguageValue;
            if(originalValue)option.value=originalValue;
          }
          const translated=source.replace(value,replacement);
          textSnapshots.set(textNode,{source,translated});
          textNode.nodeValue=translated;
        }
      }
      const elements=root instanceof Element?[root,...Array.from(root.querySelectorAll<HTMLElement>('[placeholder],[aria-label],[title]'))]:[];
      elements.forEach(element=>{
        if(element.closest('[data-no-translate],.invoice-paper'))return;
        ['placeholder','aria-label','title'].forEach(attribute=>{
          const value=element.getAttribute(attribute);
          if(!value)return;
          const snapshots=attributeSnapshots.get(element);
          const snapshot=snapshots?.get(attribute);
          if(language==='en'&&snapshot&&value===snapshot.translated){element.setAttribute(attribute,snapshot.source);return;}
          const replacement=language==='mr'?translateUiText(value,domMr):undefined;
          if(replacement&&replacement!==value){
            const next=snapshots??new Map<string,{source:string;translated:string}>();
            next.set(attribute,{source:value,translated:replacement});
            attributeSnapshots.set(element,next);
            element.setAttribute(attribute,replacement);
          }
        });
      });
    };
    const schedule=()=>{
      if(frame)return;
      frame=window.requestAnimationFrame(()=>{
        frame=0;
        const changed=[...pending];pending.clear();
        changed.forEach(translateNode);
      });
    };
    pending.add(document.body);schedule();
    const observer=new MutationObserver(records=>{
      for(const record of records){
        if(record.type==='characterData'&&record.target.parentElement?.closest('[data-no-translate],.invoice-paper'))continue;
        if(record.type==='characterData')pending.add(record.target);
        else record.addedNodes.forEach(added=>{if(!(added instanceof Element)||!added.closest('[data-no-translate],.invoice-paper'))pending.add(added)});
        if(record.type==='attributes')pending.add(record.target);
      }
      if(pending.size)schedule();
    });
    observer.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title']});
    return()=>{
      observer.disconnect();
      if(frame)window.cancelAnimationFrame(frame);
    };
  },[language]);
  const setLanguage=(next:Language)=>setLanguageState(next);
  const t=(key:string,fallback='')=>language==='mr'?(mr[key]??fallback):fallback;
  const value=useMemo(()=>({language,setLanguage,t}),[language]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}
export function useLanguage(){const value=useContext(LanguageContext);if(!value)throw new Error('useLanguage must be used inside LanguageProvider');return value}
export function LanguagePicker({compact=false}:{compact?:boolean}){const {language,setLanguage,t}=useLanguage();return <label className={`language-picker${compact?' compact':''}`}><span>{t('common.language','Language')}</span><select aria-label={t('common.language','Language')} value={language} onChange={e=>setLanguage(e.target.value as Language)}><option value="en">English</option><option value="mr">मराठी</option></select></label>}
